/**
 * Runs one check suite against this repository's built app:
 *
 *   npm run build && npm run check:smoke
 *   npm run build && npm run check:contract
 *
 * It starts `npm run start:server` and `npm run start:worker` on a free port with a fresh database
 * under data/, runs the suite, stops both processes, prints the results, and exits 0 only if every
 * check passed. `--report <file>` also writes the results as JSON.
 */
import { spawn, type ChildProcess } from 'node:child_process';
import { mkdirSync, openSync, closeSync, readFileSync, writeFileSync } from 'node:fs';
import { request } from 'node:http';
import { createServer } from 'node:net';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { setTimeout as sleep } from 'node:timers/promises';
import { CONTRACT_CHECKS } from './contract.ts';
import { SMOKE_CHECKS } from './smoke.ts';
import { runChecks, waitForHealth, type Check, type CheckContext, type Clock, type HttpClient, type SuiteReport } from './core.ts';

const SUITES: Record<string, { checks: readonly Check[]; budgetMs: number; waitForServer: boolean }> = {
  smoke: { checks: SMOKE_CHECKS, budgetMs: 30_000, waitForServer: false },
  contract: { checks: CONTRACT_CHECKS, budgetMs: 60_000, waitForServer: true },
};

const STDERR_LINES = 40;
const REQUEST_TIMEOUT_MS = 5_000;

export function parseArgs(argv: readonly string[]): { suite: string; report: string | undefined } {
  const [suite, ...rest] = argv;
  if (!suite || !(suite in SUITES)) throw new Error(`usage: cli.ts <${Object.keys(SUITES).join('|')}> [--report <file>]`);
  let report: string | undefined;
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '--report' && rest[i + 1]) report = rest[++i];
    else throw new Error(`unknown argument: ${rest[i]}`);
  }
  return { suite, report };
}

export function lastLines(text: string, n = STDERR_LINES): string[] {
  const lines = text.split(/\r?\n/);
  if (lines.at(-1) === '') lines.pop();
  return lines.slice(-n).map((l) => (l.length > 300 ? `${l.slice(0, 300)}…` : l));
}

const clock: Clock = { now: () => performance.now(), sleep: async (ms) => void (await sleep(ms)) };

function httpClient(port: number): HttpClient {
  return {
    request: (req) =>
      new Promise((resolvePromise, reject) => {
        const body = req.body === undefined ? undefined : Buffer.from(req.body);
        const headers: Record<string, string | number> = { ...(req.headers ?? {}), connection: 'close' };
        if (body) headers['content-length'] = body.length;
        const r = request({ host: '127.0.0.1', port, path: req.path, method: req.method, headers, timeout: REQUEST_TIMEOUT_MS }, (res) => {
          const chunks: Buffer[] = [];
          res.on('data', (c: Buffer) => chunks.push(c));
          res.on('end', () => {
            const text = Buffer.concat(chunks).toString('utf8');
            let json: unknown;
            try {
              json = JSON.parse(text);
            } catch {
              json = undefined;
            }
            const ct = res.headers['content-type'];
            resolvePromise({ status: res.statusCode ?? 0, contentType: Array.isArray(ct) ? ct.join(', ') : (ct ?? ''), text, json });
          });
          res.on('error', reject);
        });
        r.on('timeout', () => r.destroy(new Error(`no response within ${REQUEST_TIMEOUT_MS} ms`)));
        r.on('error', (e) => reject(new Error(`${req.method} ${req.path}: ${e.message}`)));
        r.end(body);
      }),
  };
}

function freePort(): Promise<number> {
  return new Promise((resolvePromise, reject) => {
    const s = createServer();
    s.once('error', reject);
    s.listen(0, '127.0.0.1', () => {
      const addr = s.address();
      const port = typeof addr === 'object' && addr ? addr.port : 0;
      s.close(() => resolvePromise(port));
    });
  });
}

function stopGroup(child: ChildProcess, signal: NodeJS.Signals): void {
  if (child.pid === undefined || child.exitCode !== null || child.signalCode !== null) return;
  try {
    process.kill(-child.pid, signal);
  } catch {
    // already gone
  }
}

async function main(): Promise<void> {
  const { suite, report } = parseArgs(process.argv.slice(2));
  const spec = SUITES[suite]!;
  const runDir = resolve('data', 'checks', `${suite}-${process.pid}-${Date.now()}`);
  mkdirSync(runDir, { recursive: true });
  const port = await freePort();
  const env = { ...process.env, PORT: String(port), DATABASE_PATH: join(runDir, 'jobs.db') };
  const children: Record<'server' | 'worker', ChildProcess | undefined> = { server: undefined, worker: undefined };
  const stopAll = (signal: NodeJS.Signals) => Object.values(children).forEach((c) => c && stopGroup(c, signal));
  process.once('SIGTERM', () => (stopAll('SIGKILL'), process.exit(143)));
  process.once('SIGINT', () => (stopAll('SIGKILL'), process.exit(130)));

  for (const proc of ['server', 'worker'] as const) {
    const err = openSync(join(runDir, `${proc}.stderr.txt`), 'a');
    children[proc] = spawn('npm', ['run', '--silent', `start:${proc}`], { env, detached: true, stdio: ['ignore', 'ignore', err] });
    closeSync(err);
    children[proc].on('error', () => undefined);
  }

  const ctx: CheckContext = { http: httpClient(port), clock, deadlineAt: clock.now() + spec.budgetMs };
  if (spec.waitForServer) await waitForHealth(ctx, 10_000, false).catch(() => undefined);
  const checks = await runChecks(spec.checks, ctx);

  stopAll('SIGTERM');
  const exited = (c: ChildProcess | undefined) => (c && c.exitCode === null && c.signalCode === null ? new Promise((r) => c.once('exit', r)) : Promise.resolve());
  await Promise.race([Promise.all([exited(children.server), exited(children.worker)]), sleep(5_000)]);
  stopAll('SIGKILL');

  const stderr = (proc: string) => {
    try {
      return lastLines(readFileSync(join(runDir, `${proc}.stderr.txt`), 'utf8'));
    } catch {
      return [];
    }
  };
  const result: SuiteReport = {
    schema: 'job-tracker/check-report@1',
    suite,
    passed: checks.every((c) => c.passed),
    checks,
    stderr: { server: stderr('server'), worker: stderr('worker') },
  };
  for (const c of checks) console.log(`${c.passed ? 'PASS' : 'FAIL'} ${c.name}: ${c.title}${c.passed ? '' : `\n     ${c.detail}`}`);
  console.log(`${suite}: ${checks.filter((c) => c.passed).length}/${checks.length} checks passed`);
  if (report) writeFileSync(report, `${JSON.stringify(result, null, 2)}\n`);
  process.exit(result.passed ? 0 : 1);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e: unknown) => {
    console.error(`check runner error: ${e instanceof Error ? e.message : String(e)}`);
    process.exit(2);
  });
}
/**
 * Shared machinery for the fixed build-time checks (`npm run check:smoke`, `npm run check:contract`).
 *
 * The checks use only the disclosed examples in this directory. Passing them does not mean the
 * task is complete: a separate, hidden evaluation with different cases decides acceptance.
 * Do not modify anything under checks/.
 */

export interface HttpRequest {
  method: string;
  path: string;
  headers?: Record<string, string>;
  /** Sent verbatim. No Content-Type is added unless given in `headers`. */
  body?: string;
}

export interface HttpResponse {
  status: number;
  contentType: string;
  text: string;
  /** Parsed body, or undefined when the body is not valid JSON. */
  json: unknown;
}

export interface HttpClient {
  request(req: HttpRequest): Promise<HttpResponse>;
}

export interface Clock {
  now(): number;
  sleep(ms: number): Promise<void>;
}

export interface App {
  /** Starts the server and worker. Does not wait for readiness. */
  start(): Promise<void>;
}

export interface CheckContext {
  http: HttpClient;
  clock: Clock;
  /** Absolute clock time after which waits stop early. */
  deadlineAt: number;
}

export interface Check {
  name: string;
  title: string;
  run(ctx: CheckContext): Promise<void>;
}

export interface CheckResult {
  name: string;
  title: string;
  passed: boolean;
  /** Expected versus observed, for failures. */
  detail: string;
  durationMs: number;
}

export interface SuiteReport {
  schema: 'job-tracker/check-report@1';
  suite: string;
  passed: boolean;
  checks: CheckResult[];
  /** Last lines of each process's stderr, captured by the CLI runner. */
  stderr: { server: string[]; worker: string[] };
}

export class CheckFailure extends Error {
  override name = 'CheckFailure';
}

export function expect(condition: unknown, detail: string): asserts condition {
  if (!condition) throw new CheckFailure(detail);
}

export function expectEqual(observed: unknown, expected: unknown, what: string): void {
  if (!Object.is(observed, expected)) {
    throw new CheckFailure(`${what}: expected ${JSON.stringify(expected)}, observed ${JSON.stringify(observed)}`);
  }
}

/** Polls until `probe` returns a value other than undefined, or fails after `timeoutMs`. */
export async function waitFor<T>(ctx: CheckContext, what: string, timeoutMs: number, probe: () => Promise<T | undefined>, intervalMs = 100): Promise<T> {
  const until = Math.min(ctx.clock.now() + timeoutMs, ctx.deadlineAt);
  let lastError: unknown;
  for (;;) {
    try {
      const value = await probe();
      if (value !== undefined) return value;
    } catch (e) {
      if (e instanceof CheckFailure) throw e;
      lastError = e;
    }
    const now = ctx.clock.now();
    if (now >= until) {
      const why = lastError instanceof Error ? ` (last error: ${lastError.message})` : '';
      throw new CheckFailure(`timed out after ${timeoutMs} ms waiting for ${what}${why}`);
    }
    await ctx.clock.sleep(Math.min(intervalMs, until - now));
  }
}

/** Runs every check in order; one failure never stops the others. */
export async function runChecks(checks: readonly Check[], ctx: CheckContext): Promise<CheckResult[]> {
  const results: CheckResult[] = [];
  for (const c of checks) {
    const t0 = ctx.clock.now();
    let passed = true;
    let detail = '';
    if (ctx.clock.now() >= ctx.deadlineAt) {
      passed = false;
      detail = 'not run: check time limit reached';
    } else {
      try {
        await c.run(ctx);
      } catch (e) {
        passed = false;
        detail = e instanceof Error ? e.message : String(e);
      }
    }
    results.push({ name: c.name, title: c.title, passed, detail: clip(detail, 600), durationMs: Math.round(ctx.clock.now() - t0) });
  }
  return results;
}

export function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

export const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

export function describeResponse(r: HttpResponse): string {
  return `${r.status} ${clip(r.text, 300)}`;
}

export function expectJsonResponse(r: HttpResponse, status: number, what: string): Record<string, unknown> {
  expect(r.status === status, `${what}: expected status ${status}, observed ${describeResponse(r)}`);
  expect(/^application\/json\b/i.test(r.contentType), `${what}: expected Content-Type application/json, observed ${JSON.stringify(r.contentType)}`);
  expect(isObject(r.json), `${what}: expected a JSON object body, observed ${clip(r.text, 300)}`);
  return r.json;
}

export function postJson(ctx: CheckContext, body: unknown, headers: Record<string, string> = {}): Promise<HttpResponse> {
  return ctx.http.request({
    method: 'POST',
    path: '/api/jobs',
    headers: { 'content-type': 'application/json', ...headers },
    body: JSON.stringify(body),
  });
}

export async function listJobs(ctx: CheckContext): Promise<Record<string, unknown>[]> {
  const body = expectJsonResponse(await ctx.http.request({ method: 'GET', path: '/api/jobs' }), 200, 'GET /api/jobs');
  expect(Array.isArray(body.jobs), `GET /api/jobs: expected {"jobs": [...]}, observed keys ${JSON.stringify(Object.keys(body))}`);
  return body.jobs.map((j) => (isObject(j) ? j : {}));
}

export async function getJob(ctx: CheckContext, id: string): Promise<Record<string, unknown>> {
  return expectJsonResponse(await ctx.http.request({ method: 'GET', path: `/api/jobs/${encodeURIComponent(id)}` }), 200, `GET /api/jobs/${id}`);
}

export function jobId(job: Record<string, unknown>, what: string): string {
  expect(typeof job.id === 'string' && job.id.length > 0, `${what}: expected a non-empty string "id", observed ${JSON.stringify(job.id)}`);
  return job.id;
}

/** Waits until the job leaves queued/running, then returns it. */
export function waitForFinished(ctx: CheckContext, id: string, timeoutMs: number): Promise<Record<string, unknown>> {
  return waitFor(ctx, `job ${id} to reach "completed" or "failed"`, timeoutMs, async () => {
    const job = await getJob(ctx, id);
    return job.status === 'completed' || job.status === 'failed' ? job : undefined;
  });
}

/** Waits for GET /health to answer 200 {"status":"ok"} (and, optionally, worker "up"). */
export async function waitForHealth(ctx: CheckContext, timeoutMs: number, workerUp: boolean): Promise<Record<string, unknown>> {
  const want = `GET /health to return 200 {"status":"ok"${workerUp ? ',"worker":"up"' : ''}}`;
  let last = 'no response';
  try {
    return await waitFor(ctx, want, timeoutMs, async () => {
      let r: HttpResponse;
      try {
        r = await ctx.http.request({ method: 'GET', path: '/health' });
      } catch (e) {
        last = `unreachable (${e instanceof Error ? e.message : String(e)})`;
        return undefined;
      }
      last = describeResponse(r);
      if (r.status !== 200 || !isObject(r.json) || r.json.status !== 'ok') return undefined;
      if (workerUp && r.json.worker !== 'up') return undefined;
      return r.json;
    });
  } catch {
    throw new CheckFailure(`timed out after ${timeoutMs} ms waiting for ${want}; last response: ${clip(last, 300)}`);
  }
}

