  });
}

function checkInteger(value: unknown, min: number, max: number, field: string, errors: FieldError[]): number | undefined {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    errors.push({ field, message: `${field} must be an integer.` });
    return undefined;
  }
  if (value < min || value > max) {
    errors.push({ field, message: `${field} must be between ${min} and ${max}.` });
    return undefined;
  }
  return value;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Validates a submission body. Returns the payload with defaults applied, or the field errors. */
function validateBody(req: IncomingMessage, text: string, tooLarge: boolean): { payload?: Payload; errors: FieldError[] } {
  const errors: FieldError[] = [];
  const contentType = req.headers['content-type'];
  if (!contentType || !/^application\/json\b/i.test(contentType)) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
